import React from 'react';
import PostItem from './PostItem';
import './PostList.css';

const PostList = ({ posts, loading, onEdit, onDelete }) => {
  if (loading && posts.length === 0) {
    return (
      <div className="card glass-card border-0 text-center p-5 shadow-sm">
        <div className="spinner-border text-primary mx-auto mb-3" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
        <p className="text-muted small mb-0">Loading published posts...</p>
      </div>
    );
  }

  if (posts.length === 0) {
    return (
      <section aria-labelledby="posts-heading">
        <div className="card glass-card border-0 text-center p-5 shadow-sm">
          <div className="mb-3">
            <i className="bi bi-journal-plus display-4 text-primary opacity-50"></i>
          </div>
          <h3 id="posts-heading" className="h5 fw-bold text-dark mb-2">No posts yet</h3>
          <p className="text-muted small mb-0">Create your first blog post using the form to get started.</p>
        </div>
      </section>
    );
  }

  return (
    <section aria-labelledby="posts-heading">
      <div className="d-flex align-items-center justify-content-between mb-3 px-1">
        <h2 id="posts-heading" className="h5 fw-bold mb-0 text-dark d-flex align-items-center gap-2">
          <i className="bi bi-collection-play-fill text-primary"></i>
          <span>Published Posts</span>
        </h2>
        <span className="badge bg-white text-primary border shadow-sm rounded-pill px-3 py-2">
          {posts.length} {posts.length === 1 ? 'post' : 'posts'}
        </span>
      </div>

      <div className="row g-3" role="list">
        {posts.map(post => (
          <div key={post._id} className="col-12 col-sm-6">
            <PostItem
              post={post}
              onEdit={onEdit}
              onDelete={onDelete}
            />
          </div>
        ))}
      </div>
    </section>
  );
};

export default PostList;
